public Task(int id, String description) {
    this.id = id;
    this.description = description;
    this.isCompleted = false;
}

public void markCompleted() {
    isCompleted = true;
}

public String toString() {
    return (isCompleted ? "[X] : " : "[ ] : ") + id + " : " + description;
}

// Add getters if needed

public static void main(String[] args) {
    Task t1 = new Task(1, "Buy groceries");
    System.out.println(t1);
}

public static void saveTasks(List<Task> tasks) throws IOException {
    BufferedWriter writer = new BufferedWriter(new FileWriter("tasks.txt"));
    for (Task task : tasks) {
        writer.write(task.getId() + ";" + task.getDescription() + ";" + task.isCompleted());
        writer.newLine();
    }
    writer.close();
}

public static List<Task> loadTasks() throws IOException {
    List<Task> tasks = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader("tasks.txt"));
    String line;
    while ((line = reader.readLine()) != null) {
        String[] parts = line.split(";");
        Task task = new Task(Integer.parseInt(parts[0]), parts[1]);
        if (Boolean.parseBoolean(parts[2])) task.markCompleted();
        tasks.add(task);
    }
    reader.close();
    return tasks;
}

